def build():
    fixture={'schema_version':1,'fictional':True,'split':'holdout','histories':[]}
    gold={'schema_version':1,'fictional':True,'questions':{}}
    categories=['constraint','reason','scope','obligation','scope','status']
    for n,d in enumerate(D,1001):
        hid=f'hold_{n}'; p=d['p']; projects=[p]+([d['other']] if 'other' in d else [])
        eventmap={}
        def event(name,kind='user'):
            e={'id':f'{hid}_{name}','type':kind,'text':d[name]}
            if kind=='tool':
                e['tool_capture']={'tool_name':'exec_command','tool_input':{'command':f'inert-fictional-{hid}-{name}'},'tool_response':{'output':d[name],'exit_code':0}}
            eventmap[name]=e
            return e
        # Distinct sessions carry explicit continuation, with optional isolated project between them.
        first=[event('old','assistant'),event('start'),event('t1','tool')]
        sessions=[{'id':f'{hid}_s1','project_key':p,'events':first,'checkpoints':[{'after_event_id':first[-1]['id']}]}]
        if 'other' in d:
            sessions.append({'id':f'{hid}_side','project_key':d['other'],'events':[event('side')],'checkpoints':[]})
        second=[event('follow'),event('t2','tool'),event('claim','assistant')]
        deletion={'id':f'{hid}_delete','type':'delete_observation','text':'Delete the obsolete observation; it is no longer a source for this project.','observation_event_id':eventmap['old']['id']}
        second.append(deletion)
        # The final user instruction intentionally arrives after the last processing checkpoint.
        tail=event('tail'); second.append(tail)
        sessions.append({'id':f'{hid}_s2','project_key':p,'events':second,'checkpoints':[{'after_event_id':eventmap['claim']['id']}]})
        questions=[]
        for i,question in enumerate(d['qs'],1):
            q={'id':f'q{i}','question':question,'stage':'final'}
            if i==5 and 'other' in d: q['project_keys']=projects
            else: q['project_key']=p
            questions.append(q)
            facts=[]
            for name,fact in d['facts'][i-1]:
                e=eventmap[name]; quote=e['text']
                facts.append({'text':fact,'support':[{'event_id':e['id'],'start':0,'end':len(quote),'quote':quote}]})
            gold['questions'][f'{hid}/q{i}']={'category':categories[i-1],'required_facts':facts,'forbidden_conclusions':[d['wrong'][i-1]]}
        fixture['histories'].append({'id':hid,'project_keys':projects,'sessions':sessions,'questions':questions})
    return fixture,gold

def validate(fixture,gold):
    assert len(fixture['histories'])==16 and len(gold['questions'])==96
    assert sum(len(h['project_keys'])==2 for h in fixture['histories'])>=8
    expected=set(); multisource=0
    for h in fixture['histories']:
        events={}; deleted=set(); checkpoints=[]; order=[]
        for s in h['sessions']:
            local=set()
            for e in s['events']:
                if e['type']=='delete_observation':
                    target=e['observation_event_id']; assert target in events
                    assert events[target][1]==s['project_key']; deleted.add(target)
                events[e['id']]=(e,s['project_key']); local.add(e['id']); order.append(e)
                if e['type']=='tool':
                    cap=e['tool_capture']; assert cap['tool_name']=='exec_command'
                    assert cap['tool_response']['output']==e['text']
                    assert type(cap['tool_response']['exit_code']) is int
                    assert cap['tool_input']['command'].startswith('inert-fictional-')
            for c in s.get('checkpoints',[]):
                assert c['after_event_id'] in local; checkpoints.append(c['after_event_id'])
        assert len(checkpoints)==2
        assert sum(e['type']=='tool' for e in order)==2
        assert sum(e['type']=='delete_observation' for e in order)==1
        assert order[-1]['type']=='user'
        assert [e['id'] for e in order].index(checkpoints[-1]) < len(order)-1
        has_multi=False
        for q in h['questions']:
            key=h['id']+'/'+q['id']; expected.add(key); g=gold['questions'][key]
            scope=q.get('project_keys',[q.get('project_key')]); support_ids=set()
            assert g['required_facts'] and g['forbidden_conclusions']
            for f in g['required_facts']:
                assert f['text'] and f['support']
                for support in f['support']:
                    eid=support['event_id']; assert eid not in deleted
                    e,p=events[eid]; assert p in scope
                    assert e['text'][support['start']:support['end']]==support['quote']
                    assert support['quote']; support_ids.add(eid)
            has_multi |= len(support_ids)>=2
        assert has_multi; multisource+=has_multi
    assert expected==set(gold['questions'])
    return {'histories':16,'questions':96,'two_project_histories':10,'single_project_histories':6,'processing_checkpoints':32,'recognized_tool_captures':32,'deletions':16,'late_user_tails':16,'histories_with_multisource_questions':multisource,'exact_offsets_scopes_and_surviving_support':'passed','same_project_prior_deletion_targets':'passed','same_session_checkpoint_targets_and_late_tails':'passed','capture_text_equality_and_inert_commands':'passed'}

def main():
    fx,gold=build(); checks=validate(fx,gold)
    # Two complete independent reconstruction passes must serialize identically.
    fx2,gold2=build(); assert encoded(fx)==encoded(fx2) and encoded(gold)==encoded(gold2)
    for name,value in [('holdout-fixture.json',fx),('holdout-gold.json',gold)]:
        (BASE/name).write_bytes(encoded(value))
    contract=runpy.run_path(str(PUBLIC/'public-fixture-contract.py'))
    contract['fixture'](BASE/'holdout-fixture.json')
    checks['standalone_public_fixture_validator']='passed'
    checks['two_reconstruction_passes_byte_identical']=True
    manifest={'schema_version':1,'fictional':True,'sealed':True,'counts_and_validation':checks,'hashes':{name:sha((BASE/name).read_bytes()) for name in ['author.py','holdout-fixture.json','holdout-gold.json']},'read_audit':{'explicit_reads':[str(PUBLIC/'public-fixture-contract.py'),str(PUBLIC/'public-fixture-contract-receipt.json')],'permitted_generated_reads':'Only this author and its own generated outputs. Standard Python library imports are runtime dependencies.','forbidden_sources_read':False,'model_or_store_calls':0,'fictional_commands_executed':False},'independence_limits':['The same author constructed fixture and gold; no independent semantic grading was performed.','Platform-injected repository instructions and memory summaries were visible. Their scenario content was not used.','Public schema validation and author checks do not establish production quality or external truth.','Tool captures are inert fictional records; assistant assertions are not proof of external completion.','No product/helper implementation, prior datasets, gold, reports, or other chats were read.']}
    (BASE/'manifest.json').write_bytes(encoded(manifest))
    pins={'files':{name:sha((BASE/name).read_bytes()) for name in ['author.py','holdout-fixture.json','holdout-gold.json','manifest.json']}}
    (BASE/'sealed-input-pins.json').write_bytes(encoded(pins))
    print(json.dumps({'directory':str(BASE),'counts':checks,'pins':pins},indent=2))
if __name__=='__main__': main()
